#include <stdio.h>

struct p {
    int x, y;
};

int main(void)
{
    struct p a = {1, 2};
    struct p *q = &a;

    q->x = 5;
    (*q).y = 6;
    printf("%d %d\n", a.x, a.y);
    return 0;
}

#include <stdio.h>

struct p {
    int x, y;
};

void reset(struct p v)
{
    v.x = 0;
    v.y = 0;
}

int main(void)
{
    struct p a = {1, 2};

    reset(a);
    printf("%d %d\n", a.x, a.y);
    return 0;
}

